// Language layer. Each language is its own static page: index.html in English
// (served at /), Spanish at /es and Brazilian Portuguese at /pt, generated by
// tools/build-es.mjs and tools/build-pt.mjs. This script exposes the page language and the wheel
// labels, and remembers an explicit EN/ES/PT choice in the `pz-lang` cookie, which
// the server reads at / to pick the language before sending any HTML.
(function () {
  'use strict';


  // Labels drawn on the wheel.
  var WHEEL = {
    en: {
      title: 'The Designer’s Constitution',
      credit: 'Redrawn after Walter Gropius, Bauhaus curriculum, Weimar 1922',
      ground: ['Foundations of form', 'Composition, color, typography, time', 'Conscious praxis', 'Design sense, judgment, craft'],
      studies: ['Representation', 'People', 'Limits', 'Space, time and interaction', 'Systems', 'Agents'],
      materials: ['Distribution', 'Data', 'Code', 'Interface', 'Motion', 'Models', 'Language'],
      core: ['Vision', 'Trust', 'Responsibility'],
      build: 'Build',
      answers: ['What and why', 'How it works', 'How it fails', 'How it runs']
    },
    pt: {
      title: 'A Constituição do Designer',
      credit: 'Redesenhado a partir do currículo da Bauhaus de Walter Gropius, Weimar, 1922',
      ground: ['Fundamentos da forma', 'Composição, cor, tipografia, tempo', 'Práxis consciente', 'Sensibilidade de design, discernimento, ofício'],
      studies: ['Representação', 'Pessoas', 'Limites', 'Espaço, tempo e interação', 'Sistemas', 'Agentes'],
      materials: ['Distribuição', 'Dados', 'Código', 'Interface', 'Movimento', 'Modelos', 'Linguagem'],
      core: ['Visão', 'Confiança', 'Responsabilidade'],
      build: 'Construir',
      answers: ['O que e por quê', 'Como funciona', 'Como falha', 'Como opera']
    },
    es: {
      title: 'La constitución del Diseñador',
      credit: 'Redibujado a partir del plan de estudios de la Bauhaus de Walter Gropius, dibujado en 1922 y publicado en 1923',
      ground: ['Fundamentos de forma', 'Composición, color, tipografía, tiempo', 'Praxis consciente', 'Design sense, criterio, oficio'],
      studies: ['Representación', 'Personas', 'Limitantes', 'Espacio, tiempo e interacción', 'Sistemas', 'Agentes'],
      materials: ['Distribución', 'Datos', 'Código', 'Interfaz', 'Movimiento', 'Modelos', 'Lenguaje'],
      core: ['Visión', 'Confianza', 'Responsabilidad'],
      build: 'Construir',
      answers: ['Qué y por qué', 'Cómo funciona', 'Cómo falla', 'Cómo opera']
    }
  };

  var pageLanguage = document.documentElement.lang.split('-')[0];
  var lang = Object.prototype.hasOwnProperty.call(WHEEL, pageLanguage) ? pageLanguage : 'en';
  var listeners = [];
  var selectionVersion = 0;

  // Production uses the clean URLs; previews and file:// follow the files.
  function urlFor(next) {
    if (location.hostname === 'constitution.design') return next === 'en' ? '/' : '/' + next;
    var path = location.pathname.replace(/\/index\.html$/, '/');
    var root = lang === 'en' ? path.replace(/\/?$/, '/') : path.replace(/(?:es|pt)\/?$/, '');
    return root + (next === 'en' ? 'index.html' : next + '/index.html');
  }

  function choose(next) {
    if (!Object.prototype.hasOwnProperty.call(WHEEL, next)) return;
    var version = ++selectionVersion;
    var secure = location.protocol === 'https:' ? '; Secure' : '';
    try { document.cookie = 'pz-lang=' + next + '; Path=/; Max-Age=31536000; SameSite=Lax' + secure; } catch (e) {}
    if (next === lang) return;
    var navigate = function () {
      if (version !== selectionVersion) return;
      location.href = urlFor(next) + location.hash;
    };
    if (window.PZTrack) {
      window.PZTrack('language_change', {
        language_from: lang,
        language_to: next
      }, navigate);
    } else {
      navigate();
    }
  }

  window.PZLang = {
    get: function () { return lang; },
    wheel: function () { return WHEEL[lang]; },
    onChange: function (fn) { listeners.push(fn); },
    set: choose
  };

  // This script sits at the end of <body>, so the page is already parsed.
  document.querySelectorAll('.lang button').forEach(function (b) {
    b.addEventListener('click', function () { choose(b.dataset.lang); });
  });
})();
